import { adapty, SubscriptionBillingPlan } from 'react-native-adapty';

const profile = await adapty.getProfile();
const premium = profile.accessLevels?.['premium'];

if (premium?.billingPlan === SubscriptionBillingPlan.Monthly && premium.commitmentInfo) {
  const { billingPeriodNumber, totalBillingPeriods, expiresAt } = premium.commitmentInfo;
  // e.g. "Payment 3 of 12, commitment ends on <expiresAt>"
}
